#!/usr/bin/env node
// Checks the Neovim plugin layout (root colors/ and lua/) generated by vim/scripts/build.js.
// If nvim is on PATH, also loads every colorscheme and the Lua module headless.

const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const { THEME_PALETTES } = require('../shared/palettes');

const ROOT = path.join(__dirname, '..');
const variants = Object.keys(THEME_PALETTES).map((id) => id.replace(/-/g, '_'));
const read = (...p) => fs.readFileSync(path.join(ROOT, ...p), 'utf8');

for (const v of variants) {
  const file = `stranger_${v}.vim`;
  const vim = read('vim', 'colors', file);
  assert.strictEqual(read('colors', file), vim, `colors/${file} differs from vim/colors/${file}`);

  for (const guard of [
    "get(g:, 'stranger_transparent_background', 0)",
    "get(g:, 'stranger_disable_italic', 0)",
    "get(g:, 'stranger_dim_inactive', 0)",
  ]) {
    assert.ok(vim.includes(guard), `${file}: missing option guard ${guard}`);
  }
  for (const group of ['GitSignsAdd', 'NvimTreeFolderName', 'NeoTreeDirectoryName', 'IblIndent', 'IndentBlanklineChar',
    'WhichKeyGroup', 'TroubleText', 'CmpItemKindFunction', 'BlinkCmpMenu', 'LazyNormal', 'DapBreakpoint',
    '@lsp.type.enumMember', '@lsp.mod.deprecated']) {
    assert.ok(vim.includes(` ${group} `) || vim.includes(`'${group}'`), `${file}: missing highlight group ${group}`);
  }

  const lualine = read('lua', 'lualine', 'themes', `stranger_${v}.lua`);
  const id = Object.keys(THEME_PALETTES).find((k) => k.replace(/-/g, '_') === v);
  const base = THEME_PALETTES[id].base;
  for (const key of ['BG', 'FG', 'SELECTION', 'PINK', 'GREEN', 'PURPLE', 'RED', 'YELLOW', 'CYAN', 'COMMENT']) {
    assert.ok(lualine.includes(base[key]), `lualine/themes/stranger_${v}.lua: missing ${key} ${base[key]}`);
  }
}

const init = read('lua', 'stranger-theme', 'init.lua');
for (const v of variants) assert.ok(init.includes(`'${v}'`), `init.lua: missing variant ${v}`);
for (const s of ['function M.setup', 'function M.load', 'vim.g.stranger_transparent_background',
  'vim.g.stranger_disable_italic', 'vim.g.stranger_dim_inactive']) {
  assert.ok(init.includes(s), `init.lua: missing ${s}`);
}

const which = spawnSync('nvim', ['--version'], { encoding: 'utf8' });
if (which.error) {
  console.log('notice: nvim not found on PATH, skipping headless load test');
} else {
  const lua = [
    `vim.opt.rtp:prepend(${JSON.stringify(ROOT)})`,
    'vim.opt.termguicolors = true',
    ...variants.map((v) => `vim.cmd.colorscheme('stranger_${v}')`),
    "require('stranger-theme').setup({ variant = 'the-lab', transparent = true, italic = false, dim_inactive = true })",
    "assert(vim.g.colors_name == 'stranger_the_lab', 'setup did not apply the variant')",
    "assert(vim.api.nvim_get_hl(0, { name = 'Normal' }).bg == nil, 'transparent Normal still has a bg')",
    "require('stranger-theme').load('hawkins')",
    ...variants.map((v) => `assert(type(require('lualine.themes.stranger_${v}').normal.a.bg) == 'string')`),
  ].join('\n');
  const res = spawnSync('nvim', ['--headless', '-u', 'NONE', '-i', 'NONE', '-n', '-c', `lua ${lua.replace(/\n/g, '; ')}`, '-c', 'qa!'], { encoding: 'utf8' });
  const out = `${res.stdout}${res.stderr}`;
  assert.strictEqual(res.status, 0, `nvim exited ${res.status}: ${out}`);
  assert.ok(!/E\d+:|Error/.test(out), `nvim reported errors:\n${out}`);
  console.log('nvim headless load: ok');
}

console.log(`Neovim layout: ok (${variants.length} variants)`);
